import assert from 'node:assert/strict';
import { test } from 'node:test';
import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createHash } from 'node:crypto';
import { tmpdir } from 'node:os';
import { wrapGeneratedMcp, buildSupportMcpEvents, supportMcpEventsBuildPlugin } from './support-mcp-events-build.mjs';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const banner='// AUTO-GENERATED by @lovable.dev/mcp-js — do not edit. Regenerated by the Vite plugin.';
const sdk='import { createSupabaseHandler } from "npm:@lovable.dev/mcp-js@0.23.0/stacks/supabase";';
const anchor='Deno.serve(createSupabaseHandler(mcp_default, { functionName: "mcp" }));';
const fixture=`${banner}\n// tool and issuer payload preserved\n${sdk}\n${anchor}\n`;
test('narrow anchor wrapper is exactly idempotent',()=>{
  const once=wrapGeneratedMcp(fixture);assert.equal(wrapGeneratedMcp(once),once);assert.equal(once.split('SINTAGMA_SUPPORT_MCP_EVENTS_POSTBUILD_V1').length-1,1);assert.ok(once.startsWith(banner));
});
for(const [name,source]of[
  ['unknown banner',fixture.replace(banner,'// manual')],['duplicate anchor',fixture+anchor],['unknown SDK',fixture.replace('@0.23.0/','@0.24.0/')],
  ['unknown handler variable',fixture.replace('mcp_default','different')],['unknown shape',fixture.replace('functionName: "mcp"','functionName: "other"')],
  ['partial marker',fixture.replace(anchor,'// SINTAGMA_SUPPORT_MCP_EVENTS_POSTBUILD_V1\n'+anchor)],
])test(`fails closed: ${name}`,()=>assert.throws(()=>wrapGeneratedMcp(source),/^Error: unsupported_mcp_sdk_/));
test('Vite registers a sequential post closeBundle only on build',()=>{
  const p=supportMcpEventsBuildPlugin(root);assert.equal(p.enforce,'post');assert.equal(p.apply,'build');assert.equal(p.closeBundle.order,'post');assert.equal(p.closeBundle.sequential,true);
});

test('build resolves the SDK declared esbuild without a root hoist',async()=>{
  const isolated=await fs.mkdtemp(path.join(tmpdir(),'support-mcp-sdk-dependency-'));
  try {
    const sdkDir=path.join(isolated,'node_modules/@lovable.dev/mcp-js');
    const esbuildDir=path.join(sdkDir,'node_modules/esbuild');
    const entry=path.join(isolated,'supabase/functions/mcp/index.ts');
    const shared=path.join(isolated,'supabase/functions/_shared/support-mcp-events');
    await Promise.all([fs.mkdir(path.join(sdkDir,'dist'),{recursive:true}),fs.mkdir(esbuildDir,{recursive:true}),fs.mkdir(path.dirname(entry),{recursive:true}),fs.mkdir(shared,{recursive:true})]);
    await Promise.all([
      fs.writeFile(path.join(isolated,'package.json'),'{"private":true}'),
      fs.writeFile(path.join(sdkDir,'package.json'),JSON.stringify({name:'@lovable.dev/mcp-js',version:'0.23.0',main:'./dist/index.cjs',dependencies:{esbuild:'^0.27.0'}})),
      fs.writeFile(path.join(sdkDir,'dist/index.cjs'),'module.exports = {};'),
      fs.writeFile(path.join(esbuildDir,'package.json'),'{"name":"esbuild","version":"0.27.0","main":"index.cjs"}'),
      fs.writeFile(path.join(esbuildDir,'index.cjs'),'exports.build = async options => { if (options.platform !== "neutral" || options.format !== "esm") throw new Error("wrong_bundle_options"); return {outputFiles:[{contents:new TextEncoder().encode("// nested SDK esbuild result\\n")}]} };'),
      fs.writeFile(entry,fixture),fs.writeFile(path.join(shared,'runtime-entry.ts'),'export {};'),
    ]);
    await assert.rejects(fs.access(path.join(isolated,'node_modules/esbuild')),e=>e.code==='ENOENT');
    const result=await buildSupportMcpEvents(isolated);
    assert.equal(result.sdkVersion,'0.23.0');
    assert.equal(await fs.readFile(path.join(shared,'runtime.bundle.mjs'),'utf8'),'// nested SDK esbuild result\n');
    assert.equal(await fs.readFile(entry,'utf8'),wrapGeneratedMcp(fixture));
  } finally {
    const cleanup=path.resolve(isolated);
    assert.equal(path.dirname(cleanup),path.resolve(tmpdir()));
    assert.ok(path.basename(cleanup).startsWith('support-mcp-sdk-dependency-'));
    await fs.rm(cleanup,{recursive:true,force:true});
  }
});
test('actual PR208 generated 14-tool/issuer bytes survive two bundle passes',async()=>{
  const entry=path.join(root,'supabase/functions/mcp/index.ts');
  const before=await fs.readFile(entry,'utf8');const marker='// lovable-mcp-supabase-entry.ts';
  assert.equal(before.split(marker).length,2);const prefix=before.split(marker)[0];
  const tools=['whoami','get_my_profile','search_sintagma_invoices','get_sintagma_invoice_export','search_sintagma_billing_organizations','preview_sintagma_invoice_act','create_sintagma_invoice_act','get_sintagma_postpaid_billing_overview','prepare_sintagma_postpaid_statement','preview_sintagma_postpaid_statement','approve_sintagma_postpaid_statement','issue_sintagma_postpaid_invoice','search_sintagma_support_requests','get_sintagma_support_request'];
  for(const name of tools)assert.equal(prefix.split(`name: "${name}"`).length-1,1,name);
  assert.ok(prefix.includes('acceptedAudiences: "authenticated"'));assert.ok(prefix.includes('auth: auth.oauth.issuer({'));
  const first=await buildSupportMcpEvents(root),second=await buildSupportMcpEvents(root);
  const after=await fs.readFile(entry,'utf8');assert.equal(after.split(marker)[0],prefix);assert.equal(first.entrySha256,second.entrySha256);assert.equal(first.adapterSha256,second.adapterSha256);assert.equal(second.alreadyWrapped,true);
  const bundled=await fs.readFile(path.join(root,'supabase/functions/_shared/support-mcp-events/runtime.bundle.mjs'),'utf8');
  assert.ok(bundled.includes('npm:@supabase/supabase-js@2.90.1'));assert.ok(!bundled.includes('sourceMappingURL='));
  const worker=await fs.readFile(path.join(root,'supabase/functions/support-event-delivery/index.ts'),'utf8');
  const workerVersion=/from ['"]npm:@supabase\/supabase-js@([^'"]+)['"]/.exec(worker)?.[1];
  assert.equal(workerVersion,'2.90.1');assert.ok(bundled.includes(`npm:@supabase/supabase-js@${workerVersion}`));
  const typesPackage=JSON.parse(await fs.readFile(path.join(root,'node_modules/@supabase/supabase-js/package.json'),'utf8'));
  assert.equal(typesPackage.version,workerVersion);
  const actualSha=createHash('sha256').update(prefix).digest('hex');assert.match(actualSha,/^[a-f0-9]{64}$/);
});
